    async function mergeTenderPdfs(){
        const {PDFDocument}=window.PDFLib,w=S().state.tenderDocuments.workspace,merged=await PDFDocument.create();let sourceBytes=0;
        const generated=await createTenderPdfBytes();
        for(let i=0;i<w.documents.length;i++){
            const row=w.documents[i];let bytes;
            if(row.kind==='Generated tender')bytes=generated;
            else if(tenderRuntimeFiles.has(row.id))bytes=new Uint8Array(await tenderRuntimeFiles.get(row.id).arrayBuffer());
            else if(row.kind==='Commercial quotation')bytes=await createQuotationPdfBytes(row);
            else bytes=await createTenderPlaceholderBytes(row);
            sourceBytes+=bytes.byteLength;
            let source;try{source=await PDFDocument.load(bytes,{ignoreEncryption:false,updateMetadata:false});}catch(error){throw new Error(`${row.name} read nahi hui. Password protection ya damaged PDF check karein.`);}
            const pages=await merged.copyPages(source,source.getPageIndices());pages.forEach(page=>merged.addPage(page));updateTenderProgress(8+Math.round(((i+1)/w.documents.length)*34),`Merging ${i+1}/${w.documents.length}: ${row.name}`);await new Promise(resolve=>setTimeout(resolve,0));
        }
        merged.setTitle(pdfSafe(`${w.id} Tender Package`));merged.setAuthor('Cosmix Engineering');merged.setCreator('Cosmix Tender Documents');
        const bytes=await merged.save({useObjectStreams:true,addDefaultPage:false,objectsPerTick:30});return {bytes,sourceBytes,pages:merged.getPageCount()};
    }

