        for(let index=1;index<=source.numPages;index++){
            const pdfPage=await source.getPage(index),base=pdfPage.getViewport({scale:1}),wanted=dpi/72,maxPixels=settings.profile==='Maximum'?3500000:6000000;let scale=wanted;if(base.width*base.height*scale*scale>maxPixels)scale=Math.sqrt(maxPixels/(base.width*base.height));const viewport=pdfPage.getViewport({scale}),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.floor(viewport.width));canvas.height=Math.max(1,Math.floor(viewport.height));const context=canvas.getContext('2d',{alpha:false});context.fillStyle='#fff';context.fillRect(0,0,canvas.width,canvas.height);await pdfPage.render({canvasContext:context,viewport,background:'rgb(255,255,255)'}).promise;const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(!blob)throw new Error(`Page ${index} image compression fail hui.`);const image=await out.embedJpg(new Uint8Array(await blob.arrayBuffer())),newPage=out.addPage([base.width,base.height]);newPage.drawImage(image,{x:0,y:0,width:base.width,height:base.height});canvas.width=1;canvas.height=1;pdfPage.cleanup();updateTenderProgress(42+Math.round((index/source.numPages)*53),`Compressing page ${index}/${source.numPages}`);await new Promise(resolve=>setTimeout(resolve,0));
        }
