    window.salesCatalogImportFile=async function(){const file=document.getElementById('catalog-file')?.files?.[0];if(!file){showToast('Excel ya CSV file select karein','warning');return;}try{let rows;if(/\.csv$/i.test(file.name)){const text=await file.text(),lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean),parse=line=>{const out=[];let cur='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'){cur+='"';i++;}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){out.push(cur);cur='';}else cur+=c;}out.push(cur);return out;},headers=parse(lines.shift()||'');rows=lines.map(line=>Object.fromEntries(parse(line).map((v,i)=>[headers[i],v])));}else{if(!window.XLSX){showToast('Excel reader load nahi hua; CSV template use karein','warning');return;}const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),sheet=wb.Sheets[wb.SheetNames[0]];rows=XLSX.utils.sheet_to_json(sheet,{defval:''});}const result=S().upsertCatalogItems(rows,file.name);showToast(`${result.added} added · ${result.updated} updated · ${result.skipped} skipped`,'success');setTimeout(()=>location.reload(),250);}catch(error){console.error(error);showToast('File read nahi hui; template headings check karein','warning');}};
