        if(!window.XLSX){
            const plain=[['COSMIX ENGINEERING'],['Equipment quotation'],[],['Quotation no.',q.id,'Client',safe(q.client),'Date',q.date],['Project / site',safe(q.project),'Attention',safe(q.attention),'Valid until',q.validUntil],[],headers,...exportRows,[],['Equipment subtotal',t.subtotal],['Freight / logistics',t.freight],['Tax / duty',t.tax],['Discount',t.discount],['Grand total',t.grandTotal],[],['Notes and terms',safe(q.notes)]];
            const csv=plain.map(row=>row.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${q.id}-Equipment-Quotation.csv`;a.click();URL.revokeObjectURL(url);showToast('Excel library load nahi hui; CSV exported','warning');return;
        }
