        const put=(rowNumber,values)=>{while(rows.length<rowNumber)rows.push(blank());rows[rowNumber-1]=blank();values.forEach(([index,value])=>{rows[rowNumber-1][index]=value;});};
        put(1,[[0,'COSMIX ENGINEERING']]);
