    window.salesSelectionPricingUpdateLine=function(id,field,value){const row=S().state.selectionPricing?.lines?.find(x=>x.id===id),patch={[field]:value};if(field==='unitPrice'&&Number(value)>0&&!row?.rateModel)Object.assign(patch,{rateModel:row.model,rateSource:'Entered rate',status:'Entered rate'});S().updateSelectionPricingLine(id,patch);const [title,html]=selectionPricingPage();setPageContent(title,html);};
    window.salesSelectionPricingFillRates=function(lineId=''){
        const sheet=S().state.selectionPricing;if(!sheet)return;
        const unresolved=sheet.lines.filter(x=>Number(x.unitPrice||0)<=0),targets=lineId?sheet.lines.filter(x=>x.id===lineId):(unresolved.length?unresolved:sheet.lines);
        if(!targets.length){showToast('Pricing sheet mein koi row available nahi','warning');return;}
        const content=`<div class="space-y-2"><div class="sales-note border-l-blue-500"><p class="font-bold">Available catalogue rates</p><p class="mt-1 text-[9px] text-slate-500">AUX model same rahega. Selected model sirf commercial rate reference ke taur par record hoga.</p></div><div class="max-h-[430px] space-y-2 overflow-auto pr-1">${targets.map(row=>{const candidates=S().selectionPricingCandidates(row.id);return `<div class="rounded-lg border border-slate-200 p-2.5"><div><p class="sales-label">${esc(row.section)} · Qty ${row.qty}</p><p class="mt-1 font-mono text-[10px] font-bold text-[#242b5f]">${esc(row.model)}</p><p class="mt-1 text-[8.5px] text-slate-400">${esc(row.description)}</p></div><div class="sales-field mt-2"><label>Apply available rate</label><select id="sp-rate-${row.id}" class="sales-select"><option value="">Select model / rate</option>${candidates.map(x=>`<option value="${esc(x.model)}" ${x.model===row.rateModel?'selected':''}>${x.recommended?'Recommended · ':''}${esc(x.model)} · ${money(x.price)} · ${esc(x.source)}</option>`).join('')}</select>${candidates.length?'':`<p class="mt-1 text-[8px] text-amber-700">Is category ka catalogue rate available nahi. Sheet mein unit price enter karein.</p>`}</div></div>`;}).join('')}</div></div>`;
        openModal(lineId?'Select commercial rate':'Fill missing commercial rates',content,()=>{let applied=0;targets.forEach(row=>{const model=document.getElementById(`sp-rate-${row.id}`)?.value;if(model&&S().applySelectionPricingRate(row.id,model))applied++;});showToast(applied?`${applied} rate${applied===1?'':'s'} pricing sheet mein fill ho gaye`:'Koi rate select nahi hua',applied?'success':'warning');const [title,html]=selectionPricingPage();setPageContent(title,html);});
        const confirm=document.querySelector('#modal-footer button:last-child');if(confirm)confirm.innerHTML='<i class="fas fa-check mr-1"></i> Fill selected rates';
    };
