        sheet.lines.forEach((x,i)=>data.push([i+1,x.section,x.model,x.rateModel||'Not selected',x.description,Number(x.qty),x.unit,Number(x.unitPrice),Number(x.qty)*Number(x.unitPrice),x.rateSource||'Rate required']));
